import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function SellerProfile() {
    const navigate = useNavigate();
    const [profileData, setProfileData] = useState({
        firstName: 'satyashil',
        lastName: 'magare',
        email: 'satyashilmagre@gmail.com',
        phone: '7345256965',
        bio: '',
        profileImage: null
    });
    const [loading, setLoading] = useState(false);
    const [stats, setStats] = useState({
        posts: 0,
        followers: 0,
        following: 0,
        views: 0
    });
    const [editing, setEditing] = useState(false);

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadSellerStats();
    }, []);

    const loadSellerStats = async () => {
        try {
            const storedUser = localStorage.getItem('studioUser');
            if (storedUser) {
                const user = JSON.parse(storedUser);
                const vendorId = user?.vendor_id || 1;
                
                const response = await ApiService.getSellerDashboardStats(vendorId);
                if (response.success) {
                    setStats({
                        posts: response.data.totalReels || 0,
                        followers: 0, // These would come from a different API in a real implementation
                        following: 0,
                        views: 0
                    });
                }
            }
        } catch (error) {
            console.error('Error loading seller stats:', error);
        }
    };

    const handlePostsClick = () => {
        // Open the seller reels page in a new tab/window
        const win = window.open('/studio/seller/reels', '_blank');
        win.focus();
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setProfileData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFileChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setProfileData(prev => ({
                ...prev,
                profileImage: file
            }));
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        setLoading(true);
        
        try {
            // In a real implementation, this would send data to the backend
            // For now, we'll just show a success message
            setTimeout(() => {
                // Update localStorage with the new data
                try {
                    const storedUser = localStorage.getItem('studioUser');
                    if (storedUser) {
                        const user = JSON.parse(storedUser);
                        const updatedUser = {
                            ...user,
                            firstname: profileData.firstName,
                            lastname: profileData.lastName,
                            email: profileData.email,
                            telephone: profileData.phone
                        };
                        localStorage.setItem('studioUser', JSON.stringify(updatedUser));
                        toast.success('Profile updated successfully!');
                        setEditing(false);
                    }
                } catch (error) {
                    console.error('Error updating user profile:', error);
                    toast.error('Failed to update profile');
                }
            }, 1000);
        } catch (error) {
            console.error('Profile update error:', error);
            toast.error('Failed to update profile: ' + error.message);
        } finally {
            setLoading(false);
        }
    };

    const displayName = `${profileData.firstName || ''} ${profileData.lastName || ''}`.trim() || 'Seller';
    const displayEmail = profileData.email || '';
    const displayPhone = profileData.phone || 'Not provided';

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Seller Profile</h4>
                </div>
            </div>

            {/* Profile Header Card */}
            <div className="col-lg-12">
                <div className="card overflow-hidden">
                    <div className="card-body p-0">
                        <div className="bg-primary profile-bg rounded-top position-relative" style={{ height: '200px' }}>
                            <img 
                                src="/assets/images/users/avatar-1.jpg" 
                                alt={displayName} 
                                className="avatar-xl mx-auto border border-light border-3 rounded-circle position-absolute top-100 start-50 translate-middle"
                                style={{ width: '120px', height: '120px', objectFit: 'cover' }}
                            />
                        </div>
                        <div className="mt-5 px-4 pb-4">
                            <div className="text-center mb-4">
                                <h4 className="mb-2 fw-semibold">
                                    {displayName}
                                </h4>
                                <p className="text-muted mb-3">{displayEmail}</p>
                                
                                {/* Stats */}
                                <div className="row g-3 mt-4">
                                    <div className="col-lg-3 col-6">
                                        <div 
                                            className="border rounded p-3 cursor-pointer"
                                            onClick={handlePostsClick}
                                            style={{ cursor: 'pointer' }}
                                        >
                                            <h5 className="mb-1 fw-bold text-primary">{stats.posts}</h5>
                                            <p className="text-muted mb-0 small">Posts</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.followers > 1000 ? (stats.followers / 1000).toFixed(1) + 'k' : stats.followers}
                                            </h5>
                                            <p className="text-muted mb-0 small">Followers</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.following > 1000 ? (stats.following / 1000).toFixed(1) + 'k' : stats.following}
                                            </h5>
                                            <p className="text-muted mb-0 small">Following</p>
                                        </div>
                                    </div>
                                    <div className="col-lg-3 col-6">
                                        <div className="border rounded p-3">
                                            <h5 className="mb-1 fw-bold text-primary">
                                                {stats.views > 1000 ? (stats.views / 1000).toFixed(1) + 'k' : stats.views}
                                            </h5>
                                            <p className="text-muted mb-0 small">Views</p>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>

                {/* Profile Content */}
                <div className="row mt-4">
                    {/* Personal Information */}
                    <div className="col-xl-8 col-lg-6">
                        <div className="card">
                            <div className="card-header bg-primary-subtle">
                                <h4 className="card-title mb-0 text-primary">
                                    <i className="ri-user-line align-middle me-2"></i>
                                    Personal Information
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="pb-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Full Name</h6>
                                    <p className="fw-medium mb-0">{displayName}</p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Email Address</h6>
                                    <p className="fw-medium mb-0">
                                        <a href={`mailto:${displayEmail}`} className="text-primary">{displayEmail}</a>
                                    </p>
                                </div>
                                
                                <div className="py-3 border-bottom">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Phone Number</h6>
                                    <p className="fw-medium mb-0">{displayPhone}</p>
                                </div>
                                
                                <div className="pt-3">
                                    <h6 className="text-dark fs-12 text-uppercase fw-bold mb-2">Member Since</h6>
                                    <p className="fw-medium mb-0">
                                        {new Date().toLocaleDateString('en-US', { 
                                            year: 'numeric', 
                                            month: 'long', 
                                            day: 'numeric' 
                                        })}
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>

                    {/* Quick Actions */}
                    <div className="col-xl-4 col-lg-6">
                        <div className="card">
                            <div className="card-header bg-success-subtle">
                                <h4 className="card-title mb-0 text-success">
                                    <i className="ri-settings-line align-middle me-2"></i>
                                    Quick Actions
                                </h4>
                            </div>
                            <div className="card-body">
                                <div className="d-grid gap-2">
                                    <button 
                                        className="btn btn-primary"
                                        onClick={() => setEditing(true)}
                                    >
                                        <i className="ri-edit-line me-1"></i> Edit Profile
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Edit Profile Form - Only show when editing */}
                        {editing && (
                            <div className="card mt-3">
                                <div className="card-header">
                                    <h5 className="card-title mb-0">Edit Profile</h5>
                                </div>
                                <div className="card-body">
                                    <form onSubmit={handleSubmit}>
                                        <div className="mb-3">
                                            <label htmlFor="firstName" className="form-label">
                                                First Name
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="firstName"
                                                name="firstName"
                                                value={profileData.firstName}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="lastName" className="form-label">
                                                Last Name
                                            </label>
                                            <input
                                                type="text"
                                                className="form-control"
                                                id="lastName"
                                                name="lastName"
                                                value={profileData.lastName}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="email" className="form-label">
                                                Email
                                            </label>
                                            <input
                                                type="email"
                                                className="form-control"
                                                id="email"
                                                name="email"
                                                value={profileData.email}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="phone" className="form-label">
                                                Phone
                                            </label>
                                            <input
                                                type="tel"
                                                className="form-control"
                                                id="phone"
                                                name="phone"
                                                value={profileData.phone}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                            />
                                        </div>

                                        <div className="mb-3">
                                            <label htmlFor="bio" className="form-label">
                                                Bio
                                            </label>
                                            <textarea
                                                className="form-control"
                                                id="bio"
                                                name="bio"
                                                rows="4"
                                                value={profileData.bio}
                                                onChange={handleInputChange}
                                                disabled={loading}
                                                placeholder="Tell us about yourself..."
                                            ></textarea>
                                        </div>

                                        <div className="mb-3">
                                            <label className="form-label">
                                                Profile Image
                                            </label>
                                            <div className="text-center">
                                                <div className="mb-3">
                                                    <img 
                                                        src="/assets/images/users/avatar-1.jpg" 
                                                        alt="Profile" 
                                                        className="rounded-circle avatar-lg" 
                                                    />
                                                </div>
                                                <div className="input-group">
                                                    <input
                                                        type="file"
                                                        className="form-control"
                                                        accept="image/*"
                                                        onChange={handleFileChange}
                                                        disabled={loading}
                                                    />
                                                </div>
                                                <div className="form-text">
                                                    JPG, PNG formats allowed. Max size: 5MB
                                                </div>
                                            </div>
                                        </div>

                                        <div className="d-flex gap-2">
                                            <button
                                                type="button"
                                                className="btn btn-secondary"
                                                onClick={() => setEditing(false)}
                                                disabled={loading}
                                            >
                                                Cancel
                                            </button>
                                            <button
                                                type="submit"
                                                className="btn btn-primary"
                                                disabled={loading}
                                            >
                                                {loading ? (
                                                    <>
                                                        <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                                                        Saving...
                                                    </>
                                                ) : (
                                                    'Save Changes'
                                                )}
                                            </button>
                                        </div>
                                    </form>
                                </div>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
